  private val punctuation: Set[Char] = Set('.', ',', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  private def trimPunctuation(word: String): String = {
    val left = word.dropWhile(punctuation.contains)
    left.reverse.dropWhile(punctuation.contains).reverse
  }

  private def processToken(word: String): Option[String] = {
    val stripped = if (stripPunctuation) trimPunctuation(word) else word
    val cased = if (lowercase) stripped.toLowerCase else stripped

    if (cased.length < minLength) return None

    val truncated = maxLength match {
      case Some(max) if cased.length > max => cased.take(max)
      case _ => cased
    }

    if (truncated.isEmpty) None else Some(truncated)
  }

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").toVector.filter(_.nonEmpty)

    words.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(processed, TokenType.STRING, Map("position" -> i, "original" -> word))
      }
    }.toList
  }

  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val words = text.split("\\s+").toVector.filter(_.nonEmpty)
    val result = mutable.ListBuffer.empty[(String, Int, Int)]

    var currentPos = 0
    words.foreach { word =>
      val start = text.indexOf(word, currentPos)
      val end = if (start >= 0) start + word.length else currentPos

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = end
    }

    result.toList
  }

