class TokenFunctor[T](protected val internalValue: T) {
  def map[U](func: T => U): TokenFunctor[U] = new TokenFunctor(func(internalValue))

  def flatMap[U](func: T => TokenFunctor[U]): TokenFunctor[U] = func(internalValue)

  def getOrElse(default: T): T = if (internalValue == null) default else internalValue

  def get: T = internalValue
}

class TokenMonad[T](value: T) extends TokenFunctor[T](value) {
  def ap[U](funcWrapped: TokenMonad[T => U]): TokenMonad[U] =
    new TokenMonad(funcWrapped.internalValue(internalValue))
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(value)
}

// ============================================================================
// JSON Structure Tokenization
// ============================================================================

final class JsonTokenizer(pretty: Boolean = false) {
  private def toJson(value: Any): Either[String, Json] = value match {
    case json: Json => Right(json)
    case null => Right(Json.Null)
    case s: String => Right(Json.fromString(s))
    case b: Boolean => Right(Json.fromBoolean(b))
    case i: Int => Right(Json.fromInt(i))
    case l: Long => Right(Json.fromLong(l))
    case d: Double => Right(Json.fromDoubleOrNull(d))
    case bd: BigDecimal => Right(Json.fromBigDecimal(bd))
    case bd: java.math.BigDecimal => Right(Json.fromBigDecimal(BigDecimal(bd)))
    case seq: Seq[_] =>
      seq.foldLeft(Right(Vector.empty[Json]): Either[String, Vector[Json]]) { (acc, item) =>
        for {
          soFar <- acc
          json <- toJson(item)
        } yield soFar :+ json
      }.map(Json.fromValues)
    case map: Map[_, _] =>
      val converted = map.toVector.foldLeft(Right(Vector.empty[(String, Json)]): Either[String, Vector[(String, Json)]]) {
        case (acc, (k: String, v)) =>
          for {
            soFar <- acc
            json <- toJson(v)
          } yield soFar :+ (k -> json)
        case (acc, (k, _)) =>
          Left(s"JSON object keys must be strings, found: ${k.getClass.getSimpleName}")
      }
      converted.map(fields => Json.fromFields(fields))
    case _ => Left(s"Unsupported JSON value: ${value.getClass.getSimpleName}")
  }

  def tokenize(value: Any): Token = {
    val json = toJson(value).fold(err => throw new IllegalArgumentException(err), identity)
    val jsonStr = if (pretty) json.spaces2 else json.noSpaces
    Token(jsonStr, TokenType.STRUCTURED, Map("json" -> true))
  }

  def tokenizePath(value: Any, path: String): Option[Token] = {
    val json = toJson(value).fold(err => throw new IllegalArgumentException(err), identity)
    Some(json).flatMap { root =>
      val parts = path.split("\\.").toVector
      val target = parts.foldLeft(Option(root)) { (currentOpt, part) =>
        currentOpt.flatMap { current =>
          current.asObject.flatMap(_.apply(part))
            .orElse {
              if (part.forall(_.isDigit)) {
                val idx = Try(part.toInt).getOrElse(-1)
                current.asArray.flatMap(arr => arr.lift(idx))
              } else None
            }
        }
      }
      target.map(tok => tokenize(tok))
    }
  }
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

final class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,

Chunk ID: d91038
Wall time: 0.0512 seconds
Process exited with code 0
Original token count: 812
Output:
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = Set('.', ',', '!', '?', ';', ':', '\'', '"', '(', ')', '[', ']', '{', '}')

  private def trimPunctuation(word: String): String = {
    val left = word.dropWhile(punctuation.contains)
    left.reverse.dropWhile(punctuation.contains).reverse
  }

  private def processToken(word: String): Option[String] = {
    val stripped = if (stripPunctuation) trimPunctuation(word) else word
    val cased = if (lowercase) stripped.toLowerCase else stripped

    if (cased.length < minLength) return None

    val truncated = maxLength match {
      case Some(max) if cased.length > max => cased.take(max)
      case _ => cased
    }

    if (truncated.isEmpty) None else Some(truncated)
  }

  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").toVector.filter(_.nonEmpty)

    words.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(processed, TokenType.STRING, Map("position" -> i, "original" -> word))
      }
    }.toList
  }

  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    val words = text.split("\\s+").toVector.filter(_.nonEmpty)
    val result = mutable.ListBuffer.empty[(String, Int, Int)]

    var currentPos = 0
    words.foreach { word =>
      val start = text.indexOf(word, currentPos)
      val end = if (start >= 0) start + word.length else currentPos

      processToken(word).foreach { processed =>
        result += ((processed, start, end))
      }

      currentPos = end
    }

    result.toList
  }

  def countTokens(text: String): Int = tokenize(text).size
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

final class TokenizerBuilder[T] private () {
  private val normalizers = mutable.ListBuffer.empty[String => String]
  private val validators = mutable.ListBuffer.empty[T => Boolean]
  private val metadata = mutable.Map.empty[String, Any]

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] = {
    normalizers += normalizer
    this
  }

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] = {
    validators += validator
    this
  }

  def withMetadata(kv: (String, Any)*): TokenizerBuilder[T] = {
    metadata ++= kv
    this
  }

  def build(): T => Token = {
    val normalizersSnapshot = normalizers.toVector
    val validatorsSnapshot = validators.toVector
    val metadataSnapshot = metadata.toMap

    (value: T) => {
      validatorsSnapshot.foreach { validator =>
        if (!validator(value)) {
          throw new IllegalArgumentException(s"Validation failed for $value")
        }
      }

      val normalized = normalizersSnapshot.foldLeft(String.valueOf(value)) { (current, normalize) =>
        normalize(current)
      }

      Token(normalized, TokenType.STRING, metadataSnapshot)
    }
  }
}

object TokenizerBuilder {
  def apply[T](): TokenizerBuilder[T] = new TokenizerBuilder[T]()
}
